style.css:
@-moz-document domain("pinterest.com") {
body, .App {
    background-color: #ADD8E6 !important; /* light blue background */
    color: #000000 !important; /* black text for contrast */
  }

  /* Header background */
  header {
    background-color: #B0C4DE !important; /* lighter steel blue */
  }

  /* Links and buttons */
  a,
  button,
  .button,
  .PinterestButton {
    background-color: #87CEFA !important; /* sky blue */
    color: #000000 !important;
  }

  /* Pins background */
  .GrowthUnauthPin {
    background-color: #E0FFFF !important; /* light cyan for pins */
  }

  /* Card borders and shadows */
  .pinWrapper, .GrowthPinWrapper {
    border: 1px solid #ADD8E6 !important; /* subtle blue border */
    box-shadow: 0 2px 5px rgba(0,0,0,0.1) !important;
  }
}
